import { chromium } from 'playwright';
import { mkdirSync } from 'node:fs';
mkdirSync('docs/img', { recursive: true });
const browser = await chromium.launch({ args: ['--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--ignore-gpu-blocklist'] });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 }, deviceScaleFactor: 1.5, colorScheme: 'light' });
await page.goto('https://rauguiw.github.io/banc-cycle-mci/', { waitUntil: 'networkidle', timeout: 120000 });
await page.getByRole('heading', { name: 'Diagramme P-V' }).waitFor({ timeout: 120000 });
await page.waitForTimeout(6000);
await page.screenshot({ path: 'docs/img/apercu.png' });
const card = (h) => page.locator('h2', { hasText: h }).first().locator('xpath=ancestor::*[contains(concat(" ", normalize-space(@class), " "), " card ")][1]');
const b3d = card('Banc 3D');
await b3d.scrollIntoViewIfNeeded(); await page.waitForTimeout(3000);
await b3d.screenshot({ path: 'docs/img/banc-3d.png' });
const diag = page.locator('h2', { hasText: 'Diagramme P-V' }).first().locator('xpath=ancestor::div[contains(@class, "grid")][1]');
await diag.scrollIntoViewIfNeeded(); await page.waitForTimeout(1000);
await diag.screenshot({ path: 'docs/img/diagrammes.png' });
const tab = page.locator('section[aria-label="Tableaux de résultats"]');
await tab.scrollIntoViewIfNeeded(); await page.waitForTimeout(500);
await tab.screenshot({ path: 'docs/img/points-etat.png' });
await browser.close();
